// Manual release check; consumes disposable credentials generated by the release operator.
// Never run against business identities. The operator removes fixtures after this check.
import fs from "node:fs";
import assert from "node:assert/strict";
import { randomUUID } from "node:crypto";
import { chromium } from "@playwright/test";
import { createClient } from "@supabase/supabase-js";
const meta = JSON.parse(fs.readFileSync(".e2e-meta.json", "utf8"));
const url = "https://ttmrywjzmdfjsvuxgmpr.supabase.co";
const client = createClient(
  url,
  "sb_publishable_H4kyO085uXlYX3HBvGQCsA_sO2-LDxr",
  { auth: { persistSession: false } },
);
const login = await client.auth.signInWithPassword({
  email: meta.email,
  password: meta.password,
});
if (login.error) throw login.error;
const productId = randomUUID();
const { error: productError } = await client.rpc("save_product", {
  payload: {
    id: productId,
    sku: meta.tag,
    name: meta.tag + " Essential",
    category: "Disposable QA",
    mrp_paise: 30000,
    retail_paise: 25000,
    wholesale_paise: 20000,
    variants: [
      { colour: "Rose", size: "30", stock: 10 },
      { colour: "Rose", size: "32", stock: 10 },
    ],
  },
});
if (productError) throw productError;
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1440, height: 1000 } });
const pageErrors = [];
page.on("pageerror", (e) => pageErrors.push(e.message));
try {
  await page.goto(process.env.TEST_BASE_URL || "https://feelina.vercel.app");
  await page
    .getByRole("textbox", { name: "Email address", exact: true })
    .fill(meta.email);
  await page.getByLabel("Password", { exact: true }).fill(meta.password);
  await page.getByRole("button", { name: "Sign in", exact: true }).click();
  await page
    .getByRole("heading", { name: "A little clarity for your day." })
    .waitFor({ timeout: 30000 });
  await page.getByRole("button", { name: "Create order", exact: true }).click();
  await page.getByRole("button", { name: "Add product", exact: true }).click();
  await page.getByPlaceholder("Search product name or SKU").fill(meta.tag);
  await page.locator(".product-picker button").click();
  await page
    .getByRole("spinbutton", {
      name: `${meta.tag} Essential, Rose, size 30 quantity`,
      exact: true,
    })
    .fill("3");
  await page.getByRole("button", { name: "Add customer", exact: true }).click();
  const dialog = page.getByRole("dialog");
  await dialog
    .getByLabel("Contact name", { exact: true })
    .fill(meta.tag + " Contact");
  await dialog
    .getByLabel("Shop / business name", { exact: true })
    .fill(meta.tag + " Shop");
  await dialog
    .getByLabel("Billing address", { exact: true })
    .fill("Disposable test address");
  await dialog
    .getByRole("button", { name: "Save customer", exact: true })
    .click();
  await dialog.waitFor({ state: "hidden" });
  assert.equal(
    await page
      .getByRole("spinbutton", {
        name: `${meta.tag} Essential, Rose, size 30 quantity`,
        exact: true,
      })
      .inputValue(),
    "3",
  );
  await page.getByRole("button", { name: "Save draft", exact: true }).click();
  await page
    .getByText("ORDER FORM", { exact: true })
    .waitFor({ timeout: 30000 });
  const orderId = page.url().split("#orders/")[1];
  assert.ok(orderId);
  await page.reload();
  await page
    .getByText("ORDER FORM", { exact: true })
    .waitFor({ timeout: 30000 });
  assert.ok(
    (await page.locator(".order-document").innerText()).includes("600.00"),
  );
  await page
    .getByRole("button", { name: "Mark submitted", exact: true })
    .click();
  await page
    .getByRole("button", { name: "Confirm & reserve stock", exact: true })
    .waitFor();
  await page
    .getByRole("button", { name: "Confirm & reserve stock", exact: true })
    .click();
  await page
    .getByRole("alert")
    .filter({ hasText: "Verify business" })
    .waitFor();
  const order = await client
    .from("orders")
    .select("total_paise,status,customer_id")
    .eq("id", orderId)
    .single();
  if (order.error) throw order.error;
  assert.equal(order.data.total_paise, 60000);
  assert.equal(order.data.status, "submitted");
  const { error: approvalError } = await client.rpc("update_profile", {
    p_user_id: meta.retailerId,
    p_role: "retailer",
    p_status: "active",
    p_customer_id: order.data.customer_id,
  });
  if (approvalError) throw approvalError;
  const retailer = createClient(
    url,
    "sb_publishable_H4kyO085uXlYX3HBvGQCsA_sO2-LDxr",
    { auth: { persistSession: false } },
  );
  const retailerLogin = await retailer.auth.signInWithPassword({
    email: meta.retailerEmail,
    password: meta.password,
  });
  if (retailerLogin.error) throw retailerLogin.error;
  const own = await retailer.from("orders").select("id");
  if (own.error) throw own.error;
  assert.deepEqual(
    own.data.map((x) => x.id),
    [orderId],
  );
  const denied = await retailer.rpc("adjust_stock", {
    p_variant_id: randomUUID(),
    p_quantity: 1,
    p_note: "forbidden QA",
    p_request_id: randomUUID(),
  });
  assert.ok(denied.error);
  await client.rpc("update_profile", {
    p_user_id: meta.retailerId,
    p_role: "retailer",
    p_status: "suspended",
    p_customer_id: order.data.customer_id,
  });
  const revoked = await retailer.from("orders").select("id");
  assert.deepEqual(revoked.data, []);
  await retailer.auth.signOut();
  await page.locator(".profile-button").click();
  await page.getByRole("heading", { name: "Welcome to Feelina" }).waitFor();
  assert.deepEqual(pageErrors, []);
  console.log(
    JSON.stringify({
      passed: true,
      checks: [
        "real password sign-in",
        "catalogue selection",
        "inline customer retains matrix",
        "server draft creation",
        "reload persistence",
        "submission",
        "unverified confirmation denied",
        "retailer own order access",
        "retailer stock mutation denied",
        "status revocation with existing token",
        "sign out",
      ],
      orderId,
      tag: meta.tag,
    }),
  );
} finally {
  await browser.close();
  await client.auth.signOut();
}
